import subprocess
# Find which page Limitations starts, Conclusion ends
result = subprocess.run(['pdftotext', '-layout', 'main.pdf', '-'], capture_output=True, text=True)
text = result.stdout
lines = text.split('\n')
page_num = 1
for line in lines:
    if '\f' in line:
        page_num += 1
    if 'Limitations' == line.strip() or line.strip().startswith('Limitations'):
        print(f'Limitations starts on page {page_num}: {line.strip()[:80]}')
    if 'Conclusion' in line.strip() and ('6' in line.strip()[:5] or '7' in line.strip()[:5] or line.strip().startswith('Conclusion')):
        print(f'Conclusion heading on page {page_num}: {line.strip()[:80]}')
    if 'References' == line.strip() or line.strip().startswith('References'):
        print(f'References starts on page {page_num}: {line.strip()[:80]}')
    if 'Appendix' in line.strip() or line.strip().startswith('A ') and page_num > 8:
        print(f'Appendix marker on page {page_num}: {line.strip()[:80]}')
print(f'Total pages: {page_num}')
"

